    def hidden_post_visible_groups_map
      ids = hidden_post_visible_groups.to_s.split("|").map(&:to_i)
      if ids.include?(Group::AUTO_GROUPS[:everyone]) && granular_anonymous_and_logged_in_groups_permissions
        ids = ids.map { |id| id == Group::AUTO_GROUPS[:everyone] ? Group::AUTO_GROUPS[:logged_in_users] : id }.uniq
      end
      ids
    end
